// src/hooks/useBookings.js
// Returns live bookings list for the current user + booking actions.

import { useEffect, useState, useCallback } from "react";
import { db } from "../services/firebase";
import {
  ref, onValue, push, remove, query,
  orderByChild, equalTo, set
} from "firebase/database";

export function useBookings(userId) {
  const [bookings,       setBookings]       = useState([]);
  const [allBookings,    setAllBookings]    = useState([]); // for admin
  const [deliveryStatus, setDeliveryStatus] = useState("No Booking");

  // User bookings (for delivery status)
  useEffect(() => {
    if (!userId) return;
    const q    = query(ref(db, "bookings"), orderByChild("userId"), equalTo(userId));
    const unsub = onValue(q, (snap) => {
      if (!snap.exists()) { setDeliveryStatus("No Booking"); return; }
      let last = "";
      snap.forEach((c) => (last = c.val().status));
      setDeliveryStatus(last);
    });
    return unsub;
  }, [userId]);

  // All bookings (admin view)
  useEffect(() => {
    const unsub = onValue(ref(db, "bookings"), (snap) => {
      const list = [];
      snap.forEach((c) => list.push({ key: c.key, ...c.val() }));
      setAllBookings(list);
    });
    return unsub;
  }, []);

  // History for user dashboard
  useEffect(() => {
    const unsub = onValue(ref(db, "history"), (snap) => {
      const list = [];
      snap.forEach((c) => list.push({ key: c.key, ...c.val() }));
      setBookings(list);
    });
    return unsub;
  }, []);

  const manualBook = useCallback((uid) => {
    return push(ref(db, "bookings"), {
      userId: uid,
      date:   new Date().toLocaleDateString(),
      status: "Pending",
    });
  }, []);

  const autoBook = useCallback((uid) => {
    return push(ref(db, "bookings"), {
      userId: uid,
      date:   new Date().toLocaleDateString(),
      status: "Pending",
      type:   "Auto",
    });
  }, []);

  const updateStatus = useCallback((id, status) => {
    return set(ref(db, `bookings/${id}/status`), status);
  }, []);

  const cancelBooking = useCallback((id) => {
    return remove(ref(db, `bookings/${id}`));
  }, []);

  const cancelHistory = useCallback((id) => {
    return remove(ref(db, `history/${id}`));
  }, []);

  const clearHistory = useCallback(() => {
    return remove(ref(db, "history"));
  }, []);

  return {
    bookings,
    allBookings,
    deliveryStatus,
    manualBook,
    autoBook,
    updateStatus,
    cancelBooking,
    cancelHistory,
    clearHistory,
  };
}
