// src/hooks/useNotifications.js
// Real-time in-app notifications stored in Firebase.

import { useEffect, useState, useCallback } from "react";
import { db } from "../services/firebase";
import { ref, onValue, push, set, remove } from "firebase/database";

export function useNotifications(userId) {
  const [notifications, setNotifications] = useState([]);
  const unreadCount = notifications.filter((n) => !n.read).length;

  useEffect(() => {
    if (!userId) return;
    return onValue(ref(db, `notifications/${userId}`), (snap) => {
      const list = [];
      snap.forEach((c) => list.push({ key: c.key, ...c.val() }));
      setNotifications(list.reverse());
    });
  }, [userId]);

  const addNotification = useCallback((uid, message, type = "info") => {
    return push(ref(db, `notifications/${uid}`), {
      message,
      type,
      read:      false,
      timestamp: Date.now(),
      time:      new Date().toLocaleTimeString(),
    });
  }, []);

  const markRead = useCallback((uid, notifKey) => {
    return set(ref(db, `notifications/${uid}/${notifKey}/read`), true);
  }, []);

  const markAllRead = useCallback((uid) => {
    notifications.forEach((n) => {
      if (!n.read) set(ref(db, `notifications/${uid}/${n.key}/read`), true);
    });
  }, [notifications]);

  const clearAll = useCallback((uid) => {
    return remove(ref(db, `notifications/${uid}`));
  }, []);

  return { notifications, unreadCount, addNotification, markRead, markAllRead, clearAll };
}
