// src/components/Navbar.jsx
import React from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { auth } from "../services/firebase";
import { signOut } from "firebase/auth";
import { useToast } from "../context/ToastContext";
import { useNotifications } from "../hooks/useNotifications";

export default function Navbar({ userId }) {
  const navigate      = useNavigate();
  const location      = useLocation();
  const { showToast } = useToast();
  const { unreadCount } = useNotifications(userId);

  const logout = () => {
    signOut(auth).then(() => {
      localStorage.clear();
      showToast("Logged Out Successfully 👋", "info");
      setTimeout(() => navigate("/"), 1000);
    });
  };

  const isActive = (path) => location.pathname === path;

  const navBtn = (path, label) => (
    <button
      onClick={() => navigate(path)}
      style={{
        background:   isActive(path) ? "rgba(239,68,68,0.2)" : "transparent",
        border:       isActive(path) ? "1px solid rgba(239,68,68,0.4)" : "1px solid transparent",
        padding:      "7px 14px",
        borderRadius: "8px",
        color:        isActive(path) ? "#ef4444" : "#aaa",
        cursor:       "pointer",
        fontSize:     "13px",
        fontFamily:   "Poppins, sans-serif",
        transition:   ".2s",
        position:     "relative",
      }}
    >
      {label}
    </button>
  );

  return (
    <div style={{
      display:        "flex",
      justifyContent: "space-between",
      alignItems:     "center",
      padding:        "13px 20px",
      background:     "#0f172a",
      flexWrap:       "wrap",
      gap:            "10px",
    }}>
      {/* Logo */}
      <div style={{ fontSize:"20px", fontWeight:"bold", color:"#ef4444", cursor:"pointer" }}
        onClick={() => navigate("/dashboard")}>
        🔥 Smart Gas
      </div>

      {/* Nav links */}
      <div style={{ display:"flex", gap:"6px", alignItems:"center", flexWrap:"wrap" }}>
        {navBtn("/dashboard", "🏠 Dashboard")}
        {navBtn("/support",   "🎧 Support")}

        {/* Profile with unread badge */}
        <button
          onClick={() => navigate("/profile")}
          style={{
            background:   isActive("/profile") ? "rgba(239,68,68,0.2)" : "transparent",
            border:       isActive("/profile") ? "1px solid rgba(239,68,68,0.4)" : "1px solid transparent",
            padding:      "7px 14px",
            borderRadius: "8px",
            color:        isActive("/profile") ? "#ef4444" : "#aaa",
            cursor:       "pointer",
            fontSize:     "13px",
            fontFamily:   "Poppins, sans-serif",
            transition:   ".2s",
            position:     "relative",
          }}
        >
          👤 Profile
          {unreadCount > 0 && (
            <span style={{
              position:     "absolute",
              top:          "-6px",
              right:        "-6px",
              background:   "#ef4444",
              color:        "white",
              borderRadius: "50%",
              width:        "18px",
              height:       "18px",
              fontSize:     "10px",
              display:      "flex",
              alignItems:   "center",
              justifyContent: "center",
              fontWeight:   700,
            }}>
              {unreadCount > 9 ? "9+" : unreadCount}
            </span>
          )}
        </button>

        {userId && (
          <span style={{ fontSize:"12px", opacity:0.4, padding:"0 4px" }}>
            {userId}
          </span>
        )}

        <button
          onClick={logout}
          style={{
            background:   "#ef4444",
            padding:      "8px 16px",
            border:       "none",
            borderRadius: "8px",
            color:        "white",
            cursor:       "pointer",
            fontSize:     "13px",
            fontFamily:   "Poppins, sans-serif",
          }}
        >
          Logout
        </button>
      </div>
    </div>
  );
}
