// src/pages/DashboardPage.jsx
import React, { useEffect, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { useToast } from "../context/ToastContext";
import { useGasData } from "../hooks/useGasData";
import { useBookings } from "../hooks/useBookings";
import Navbar from "../components/Navbar";
import CylinderSVG from "../components/CylinderSVG";
import GasChart from "../components/GasChart";

const AUTO_THRESHOLD = 20; // same as original

export default function DashboardPage() {
  const navigate          = useNavigate();
  const { currentUser }   = useAuth();
  const { showToast }     = useToast();
  const gasData           = useGasData();
  const userId            = currentUser?.phoneNumber ?? "Guest";

  const {
    bookings,
    deliveryStatus,
    manualBook,
    autoBook,
    cancelHistory,
    clearHistory,
  } = useBookings(userId);

  const [autoMode,      setAutoMode]      = useState(
    () => localStorage.getItem("autoMode") === "true"
  );
  const bookingDoneRef = useRef(false);

  // Redirect if not logged in
  useEffect(() => {
    if (!currentUser) navigate("/");
  }, [currentUser, navigate]);

  // Auto booking logic — mirrors original
  useEffect(() => {
    const p = gasData.percentage;
    if (p > 60) { bookingDoneRef.current = false; return; }

    if (p <= AUTO_THRESHOLD && !bookingDoneRef.current && autoMode) {
      autoBook(userId);
      showToast("Gas Low — Auto Booking Triggered 🤖", "warning");
      bookingDoneRef.current = true;
    }
  }, [gasData.percentage, autoMode, userId, autoBook, showToast]);

  const handleManualBook = () => {
    manualBook(userId);
    showToast("Cylinder Booking Request Sent ✅", "success");
  };

  const handleToggleAuto = () => {
    const next = !autoMode;
    setAutoMode(next);
    localStorage.setItem("autoMode", next);
  };

  const handleCancelHistory = (id) => {
    cancelHistory(id);
    showToast("Booking Cancelled ❌", "error");
  };

  const handleClearHistory = () => {
    clearHistory();
    showToast("History Cleared 🧹", "info");
  };

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;500;700&display=swap');
        * { box-sizing:border-box; }
        body { margin:0; font-family:Poppins;
               background:linear-gradient(120deg,#020617,#111827); color:white; }
        .container { display:flex; flex-wrap:wrap; gap:30px;
                     justify-content:center; padding:30px; }
        .card {
          background:rgba(255,255,255,0.05);
          padding:25px; border-radius:20px; width:320px;
          text-align:center;
          backdrop-filter:blur(8px);
        }
        .cylinder-box { width:160px; margin:auto; transition:0.5s; }
        .action-btn {
          background:#ef4444; padding:12px; border:none;
          border-radius:10px; color:white; cursor:pointer;
          width:100%; margin-top:10px; font-size:15px;
          font-family:Poppins;
        }
        .auto-btn-on  { background:#22c55e !important; }
        .auto-btn-off { background:#ef4444 !important; }
        table { width:100%; margin-top:10px; border-collapse:collapse; }
        td { padding:8px; border-bottom:1px solid #333; font-size:13px; }
        .cancel-btn {
          background:#f59e0b; padding:4px 10px;
          border-radius:6px; cursor:pointer; border:none;
          color:white; font-family:Poppins; font-size:12px;
        }
        .clear-btn {
          background:#ef4444; padding:10px; border-radius:10px;
          margin-top:10px; cursor:pointer; border:none;
          color:white; font-family:Poppins; width:100%;
        }
      `}</style>

      <Navbar userId={userId} />

      <div className="container">

        {/* ── Card 1: Cylinder Status ── */}
        <div className="card">
          <h3>Cylinder Status</h3>

          <div className="cylinder-box">
            <CylinderSVG percent={gasData.percentage} />
          </div>

          <h1 style={{ margin: "10px 0 4px" }}>
            {Math.round(gasData.percentage)}%
          </h1>
          <h3 style={{ margin: "4px 0 16px", opacity: 0.8 }}>
            Delivery: {deliveryStatus}
          </h3>

          <button className="action-btn" onClick={handleManualBook}>
            Book Cylinder
          </button>

          <button
            className={`action-btn ${autoMode ? "auto-btn-on" : "auto-btn-off"}`}
            onClick={handleToggleAuto}
          >
            🤖 Auto Booking : {autoMode ? "ON" : "OFF"}
          </button>
        </div>

        {/* ── Card 2: Gas Usage Chart ── */}
        <div className="card">
          <h3>Gas Usage Chart</h3>
          <GasChart percentage={gasData.percentage} />
        </div>

        {/* ── Card 3: Booking History ── */}
        <div className="card">
          <h3>Booking History</h3>
          <table>
            <tbody>
              {bookings.map((b) => (
                <tr key={b.key}>
                  <td>{b.date}</td>
                  <td>{b.status}</td>
                  <td>
                    <button
                      className="cancel-btn"
                      onClick={() => handleCancelHistory(b.key)}
                    >
                      Cancel
                    </button>
                  </td>
                </tr>
              ))}
              {bookings.length === 0 && (
                <tr>
                  <td colSpan={3} style={{ opacity: 0.5 }}>
                    No history yet
                  </td>
                </tr>
              )}
            </tbody>
          </table>
          <button className="clear-btn" onClick={handleClearHistory}>
            🧹 Clear History
          </button>
        </div>

      </div>
    </>
  );
}
